import {RuntimeApiError,identifier} from '../validation.js';
/** Panel-scoped presentation owner. Completed Phase3 sweeps are the only automatic refresh trigger. */
export class CollaborationOwner{
 #client;#now;#generation=0;#open=false;#fresh=false;#signature='';#sweep='';#ticks=0;#cursor='0';#failures=0;#retryAt=0;#disposed=false;
 /** @type {AbortController|null} */#controller=null;
 /** @type {Promise<void>|null} */#flight=null;
 /** @type {Set<()=>void>} */#listeners=new Set();
 /** @type {import('./contracts').Query} */#query={limit:10};
 /** @type {(string|null)[]} */#history=[null];
 /** @type {Map<string,Set<string>>} */#sectionCursors=new Map();
 /** @type {import('./contracts').State} */#state={connected:false,agentId:null,agent:null,snapshot:null,timeline:null,selectedId:null,loading:false,message:'Connect collaboration read access.',stale:true,historyOpen:false,page:1};
 /** @param {import('./api-client.js').CollaborationApiClient} client @param {{now?:()=>number}} [options] */constructor(client,options={}){this.#client=client;this.#now=options.now??Date.now;}
 getSnapshot(){return Object.freeze({...this.#state,connected:this.#client.hasCredential});}
 /** @param {()=>void} fn */subscribe(fn){this.#listeners.add(fn);return ()=>{this.#listeners.delete(fn);};}
 #emit(){if(!this.#disposed)for(const fn of this.#listeners)try{fn();}catch{}}
 #cancel(){this.#generation++;this.#controller?.abort();this.#controller=null;this.#flight=null;}
 #reset(){this.#cancel();this.#state={...this.#state,agent:null,snapshot:null,timeline:null,selectedId:null,loading:false,historyOpen:false,page:1,stale:true,message:''};this.#query={limit:10};this.#history=[null];this.#sectionCursors.clear();this.#cursor='0';this.#retryAt=0;this.#failures=0;}
 /** @param {import('../npc-binding.contracts').NpcRuntimeBinding|null|undefined} binding @param {import('../contracts').RuntimeSnapshot} [runtime] */select(binding,runtime){if(this.#disposed)return;
 if(runtime?.phase==='DISCONNECTED'||runtime?.phase==='AUTH_REQUIRED'||['AUTH_REQUIRED','FORBIDDEN','NOT_FOUND'].includes(runtime?.error?.code??'')){this.disconnect();return;}
 const b=binding?.state==='RESOLVED'?binding:null,signature=b?`${b.agentId}/${b.bindingId}/${b.npcId}`:'';
 const changed=signature!==this.#signature;if(changed){this.#reset();this.#signature=signature;this.#state={...this.#state,agentId:b?.agentId??null};this.#sweep='';this.#ticks=0;}
 this.#fresh=b?.freshness==='fresh';if(!this.#fresh)this.#state={...this.#state,stale:true};
 const stamp=b?.lastSuccessfulSyncAt??'',sweep=!!stamp&&stamp!==this.#sweep;if(stamp)this.#sweep=stamp;
 if(this.#open&&this.#fresh&&this.#client.hasCredential&&(changed||sweep||!this.#state.agent)){if(changed||!this.#state.agent)void this.refresh(false);else if(sweep)void this.#poll();}this.#emit();}
 /** @param {boolean} value */open(value){this.#open=value;if(!value){this.#cancel();this.#state={...this.#state,loading:false,stale:true};this.#emit();}else void this.refresh();}
 /** @param {(signal:AbortSignal,apply:(patch:Partial<import('./contracts').State>)=>void)=>Promise<void>} work @param {boolean} [manual] */#run(work,manual=false){if(this.#flight)return this.#flight;if(this.#disposed||!this.#open||!this.#state.agentId||!this.#fresh||!this.#client.hasCredential||!manual&&this.#now()<this.#retryAt)return Promise.resolve();
 const controller=new AbortController(),generation=this.#generation;this.#controller=controller;this.#state={...this.#state,loading:true};this.#emit();
 const apply=/** @param {Partial<import('./contracts').State>} patch */patch=>{if(!controller.signal.aborted&&generation===this.#generation)this.#state={...this.#state,...patch};};
 const flight=(async()=>{try{await work(controller.signal,apply);if(!controller.signal.aborted&&generation===this.#generation){this.#failures=0;this.#retryAt=0;apply({stale:!this.#fresh,message:''});}}
 catch(error){if(controller.signal.aborted||generation!==this.#generation)return;const code=error instanceof RuntimeApiError?error.code:'SERVER';if(['AUTH_REQUIRED','FORBIDDEN'].includes(code)){this.disconnect();this.#state={...this.#state,message:'Authorization unavailable. Protected collaboration data cleared.'};}
 else if(code==='NOT_FOUND'){apply({snapshot:null,timeline:null,selectedId:null,stale:true,message:'Collaboration or Agent is unavailable.'});}
 else{if(code==='STALE_SNAPSHOT'){this.#query={limit:10};this.#history=[null];this.#cursor='0';apply({snapshot:null,timeline:null,page:1});}this.#failures++;this.#retryAt=this.#now()+Math.min(60000,1000*2**Math.min(this.#failures,6));apply({stale:true,message:code==='STALE_SNAPSHOT'?'Cursor requires a fresh snapshot. Use Refresh.':code==='TIMEOUT'?'Request timed out. Last-known data is stale; retry safely.':'Connection or response unavailable. Last-known data is stale; retry safely.'});}}
 finally{if(this.#controller===controller){this.#controller=null;this.#flight=null;this.#state={...this.#state,loading:false};this.#emit();}}})();this.#flight=flight;return flight;}
 /** @param {import('./contracts').Snapshot} next */#accept(next){const previous=this.#state.snapshot;if(previous?.collaboration.id===next.collaboration.id){if(next.collaboration.version<previous.collaboration.version||BigInt(next.synchronization.nativeAfterPosition)<BigInt(previous.synchronization.nativeAfterPosition))throw new RuntimeApiError('STALE_SNAPSHOT');for(const list of ['delegations','external']){const old=/** @type {readonly {version:number,id?:string,mappingId?:string}[]} */(list==='delegations'?previous.delegations.items:previous.external.items);const fresh=list==='delegations'?next.delegations.items:next.external.items;for(const item of fresh){const id='id'in item?item.id:item.mappingId;const prior=old.find(v=>(v.id??v.mappingId)===id);if(prior&&prior.version>item.version)throw new RuntimeApiError('STALE_SNAPSHOT');}}}this.#cursor=next.synchronization.nativeAfterPosition;return next;}
 /** @param {string} id @param {AbortSignal} signal */async #snapshot(id,signal){let next=await this.#client.snapshot(id,this.#query,{signal});if(this.#state.snapshot&&this.#state.snapshot.collaboration.version!==next.collaboration.version&&Object.keys(this.#query).length>1){this.#query={limit:10};this.#sectionCursors.clear();next=await this.#client.snapshot(id,this.#query,{signal});}if(signal.aborted)throw new RuntimeApiError('CANCELLED');return this.#accept(next);}
 /** @param {boolean} [manual] */refresh(manual=true){return this.#run(async(signal,apply)=>{const agentId=this.#state.agentId;if(!agentId)return;const agent=await this.#client.agent(agentId,{limit:10},{signal});const id=this.#state.selectedId;const snapshot=id?await this.#snapshot(id,signal):null;const timeline=id&&this.#state.historyOpen?await this.#client.timeline(id,{limit:10,...(this.#history.at(-1)?{cursor:/** @type {string} */(this.#history.at(-1))}:{})},{signal}):null;if(!signal.aborted){this.#sectionCursors.delete('memberships');this.#sectionCursors.delete('agentExternal');}apply({agent,snapshot,timeline});},manual);}
 /** @param {string} id */openCollaboration(id){id=identifier(id);if(!this.#state.agent?.collaborations.items.some(m=>m.id===id))return Promise.resolve();this.#cancel();this.#query={limit:10};this.#history=[null];this.#sectionCursors.clear();this.#state={...this.#state,selectedId:id,snapshot:null,timeline:null,historyOpen:false,page:1};return this.refresh();}
 back(){this.#cancel();this.#state={...this.#state,selectedId:null,snapshot:null,timeline:null,loading:false};this.#emit();}
 async #poll(){if(++this.#ticks%5===0||!this.#state.selectedId)return this.#ticks%5===0?this.refresh(false):undefined;
 return this.#run(async(signal,apply)=>{const id=this.#state.selectedId;if(!id)return;let changed=false;try{const page=await this.#client.events(id,this.#cursor,{signal});changed=!!page.items.length;this.#cursor=page.nextPosition;}catch(error){if(error instanceof RuntimeApiError&&error.code==='STALE_SNAPSHOT'){this.#query={limit:10};changed=true;}else throw error;}
 if(changed||this.#state.snapshot?.external.items.length){const snapshot=await this.#snapshot(id,signal);let timeline=this.#state.timeline;if(this.#state.historyOpen&&this.#state.page===1)timeline=await this.#client.timeline(id,{limit:10},{signal});apply({snapshot,timeline});}});}
 /** @param {'participants'|'delegations'|'external'} section @param {boolean} [first] */sectionPage(section,first=false){const snapshot=this.#state.snapshot;if(!snapshot)return Promise.resolve();const cursor=first?null:snapshot[section].nextCursor;if(!first&&!cursor)return Promise.resolve();const seen=this.#sectionCursors.get(section)??new Set();if(cursor&&(seen.has(cursor)||seen.size>=20)){this.#state={...this.#state,message:'Page limit reached. Return to the first page.'};this.#emit();return Promise.resolve();}if(cursor)seen.add(cursor);else seen.clear();this.#sectionCursors.set(section,seen);const key=section==='participants'?'participantsAfter':section==='delegations'?'delegationsAfter':'externalAfter';if(cursor)this.#query[key]=cursor;else delete this.#query[key];return this.refresh();}
 /** @param {boolean} value */openHistory(value){this.#state={...this.#state,historyOpen:value};this.#emit();return value?this.historyPage('first'):Promise.resolve();}
 /** @param {'first'|'next'|'previous'} direction */historyPage(direction){const id=this.#state.selectedId;if(!id)return Promise.resolve();return this.#run(async(signal,apply)=>{let trail=[...this.#history];if(direction==='first')trail=[null];else if(direction==='previous')trail.pop();else{const cursor=this.#state.timeline?.nextCursor;if(!cursor||trail.includes(cursor)||trail.length>=20)throw new RuntimeApiError('LIMIT_EXCEEDED');trail.push(cursor);}if(!trail.length)trail=[null];const cursor=trail.at(-1),timeline=await this.#client.timeline(id,{limit:10,...(cursor?{cursor}:{})},{signal});this.#history=trail;apply({timeline,page:trail.length});},true);}
 nextMemberships(){const seen=this.#sectionCursors.get('memberships')??new Set();const after=this.#state.agent?.collaborations.nextCursor;if(!after||seen.has(after)||seen.size>=20)return Promise.resolve();seen.add(after);this.#sectionCursors.set('memberships',seen);return this.#run(async(signal,apply)=>{const agent=await this.#client.agent(/** @type {string} */(this.#state.agentId),{limit:10,after},{signal});apply({agent});},true);}
 nextAgentExternal(){const after=this.#state.agent?.external.nextCursor,seen=this.#sectionCursors.get('agentExternal')??new Set();if(!after||seen.has(after)||seen.size>=20)return Promise.resolve();seen.add(after);this.#sectionCursors.set('agentExternal',seen);return this.#run(async(signal,apply)=>{const agent=await this.#client.agent(/** @type {string} */(this.#state.agentId),{limit:10,externalAfter:after},{signal});apply({agent});},true);}
 disconnect(){this.#reset();this.#client.clearCredential();this.#state={...this.#state,agentId:null,message:'Collaboration read access disconnected.'};this.#signature='';this.#emit();}
 dispose(){if(this.#disposed)return;this.disconnect();this.#disposed=true;this.#listeners.clear();this.#client.dispose();}
}
